import math
truth = {"p1": 1, "p2": 0, "p3": 1, "p4": 0, "p5": 0}
def ndcg_at_k(order, k=3):
    dcg = sum(truth[p] / math.log2(i + 2) for i, p in enumerate(order[:k]))
    ideal = sorted(truth.values(), reverse=True)
    idcg = sum(r / math.log2(i + 2) for i, r in enumerate(ideal[:k]))
    return dcg / idcg
def recall_at_k(order, k=3):
    return sum(truth[p] for p in order[:k]) / sum(truth.values())
m1 = ["p1", "p3", "p2", "p4", "p5"]
m2 = ["p2", "p1", "p4", "p3", "p5"]
for name, o in (("모델1", m1), ("모델2", m2)):
    print(name, f"NDCG@3={ndcg_at_k(o):.3f}", f"Recall@3={recall_at_k(o):.2f}")

# 모델1 NDCG@3=1.000 Recall@3=1.00
# 모델2 NDCG@3=0.387 Recall@3=0.50
